 54	    v = (v | (v << 4)) & UINT64_C(0x0f0f0f0f0f0f0f0f);
 55	    v = (v | (v << 2)) & UINT64_C(0x3333333333333333);
 56	    v = (v | (v << 1)) & UINT64_C(0x5555555555555555);
 57	    return v;
 58	}
 59	
 60	static double center(double origin, double extent) { return origin * 0.5 + (origin + extent) * 0.5; }
 61	
 62	static uint32_t quantize(double value, double minimum, double maximum) {
 63	    double half_min = minimum * 0.5, half_max = maximum * 0.5;
 64	    double range = half_max - half_min;
 65	    if (range <= 0.0) return 0;
 66	    double normalized = (value * 0.5 - half_min) / range;
 67	    if (normalized <= 0.0) return 0;
 68	    if (normalized >= 1.0) return UINT32_MAX;
 69	    return (uint32_t)(normalized * (double)UINT32_MAX);
 70	}
 71	
 72	static int compare_entries(const void *left, const void *right) {
 73	    const packed_entry *a = left, *b = right;
 74	    if (a->morton < b->morton) return -1;
 75	    if (a->morton > b->morton) return 1;
 76	    if (a->source_index < b->source_index) return -1;
 77	    if (a->source_index > b->source_index) return 1;
 78	    return 0;
 79	}
 80	
 81	static int compare_ids(const void *left, const void *right) {
 82	    uint64_t a = *(const uint64_t *)left, b = *(const uint64_t *)right;
 83	    return a < b ? -1 : a > b ? 1 : 0;
 84	}
 85	
 86	static uint32_t build_nodes(build_context *ctx, const packed_entry *entries, size_t first, size_t end) {
 87	    uint32_t node_index = (uint32_t)ctx->next++;
 88	    packed_node *node = &ctx->nodes[node_index];
 89	    if (end - first == 1) {
 90	        node->bounds = entries[first].bounds;
 91	        node->entry = (uint32_t)first;
 92	        node->leaf = true;
 93	        return node_index;
 94	    }
 95	    size_t middle = first + (end - first) / 2;
 96	    node->left = build_nodes(ctx, entries, first, middle);
 97	    node->right = build_nodes(ctx, entries, middle, end);
 98	    node->bounds = combine(ctx->nodes[node->left].bounds, ctx->nodes[node->right].bounds);
 99	    node->leaf = false;
100	    return node_index;
101	}
