103	spatial_status spatial_index_create(const spatial_record *records, size_t count, spatial_index **out_index) {
104	    if (out_index == NULL) return SPATIAL_STATUS_INVALID;
105	    *out_index = NULL;
106	    if (count > SPATIAL_INDEX_MAX_RECORDS) return SPATIAL_STATUS_LIMIT;
107	    if (records == NULL && count != 0) return SPATIAL_STATUS_INVALID;
108	    if (count == 0) {
109	        spatial_index *empty = calloc(1, sizeof(*empty));
110	        if (empty == NULL) return SPATIAL_STATUS_OOM;
111	        *out_index = empty;
112	        return SPATIAL_STATUS_OK;
113	    }
114	    size_t entry_bytes, node_count, node_bytes, all_bytes;
115	    node_count = count * 2 - 1;
116	    if (count > SIZE_MAX / sizeof(packed_entry) || node_count > SIZE_MAX / sizeof(packed_node)) return SPATIAL_STATUS_OVERFLOW;
117	    entry_bytes = count * sizeof(packed_entry);
118	    node_bytes = node_count * sizeof(packed_node);
119	    if (entry_bytes > SIZE_MAX - node_bytes || entry_bytes + node_bytes > SIZE_MAX - count * sizeof(uint64_t)) return SPATIAL_STATUS_OVERFLOW;
120	    all_bytes = entry_bytes + node_bytes + count * sizeof(uint64_t);
121	    if (all_bytes > SPATIAL_INDEX_MAX_BYTES) return SPATIAL_STATUS_LIMIT;
122	    uint64_t *ids = malloc(count * sizeof(*ids));
123	    spatial_index *index = calloc(1, sizeof(*index));
124	    if (ids == NULL || index == NULL) { free(ids); free(index); return SPATIAL_STATUS_OOM; }
125	    index->entries = malloc(entry_bytes);
126	    index->nodes = malloc(node_bytes);
127	    if (index->entries == NULL || index->nodes == NULL) { free(ids); spatial_index_destroy(index); return SPATIAL_STATUS_OOM; }
128	    double min_x = INFINITY, min_y = INFINITY, max_x = -INFINITY, max_y = -INFINITY;
129	    double min_left = INFINITY, min_top = INFINITY, max_right = -INFINITY, max_bottom = -INFINITY;
130	    for (size_t i = 0; i < count; ++i) {
131	        spatial_bounds b = records[i].bounds;
132	        if (!bounds_valid(b)) { free(ids); spatial_index_destroy(index); return SPATIAL_STATUS_INVALID; }
133	        ids[i] = records[i].id;
134	        min_left = fmin(min_left, b.x); min_top = fmin(min_top, b.y);
135	        max_right = fmax(max_right, b.x + b.width); max_bottom = fmax(max_bottom, b.y + b.height);
136	        min_x = fmin(min_x, center(b.x, b.width)); min_y = fmin(min_y, center(b.y, b.height));
137	        max_x = fmax(max_x, center(b.x, b.width)); max_y = fmax(max_y, center(b.y, b.height));
138	        index->entries[i] = (packed_entry){b, records[i].id, 0, (uint32_t)i};
139	    }
140	    if (!isfinite(max_right - min_left) || !isfinite(max_bottom - min_top)) {
141	        free(ids); spatial_index_destroy(index); return SPATIAL_STATUS_OVERFLOW;
142	    }
143	    qsort(ids, count, sizeof(*ids), compare_ids);
144	    for (size_t i = 1; i < count; ++i) if (ids[i] == ids[i - 1]) { free(ids); spatial_index_destroy(index); return SPATIAL_STATUS_INVALID; }
145	    free(ids);
146	    for (size_t i = 0; i < count; ++i) {
147	        uint32_t qx = quantize(center(index->entries[i].bounds.x, index->entries[i].bounds.width), min_x, max_x);
148	        uint32_t qy = quantize(center(index->entries[i].bounds.y, index->entries[i].bounds.height), min_y, max_y);
149	        index->entries[i].morton = spread_bits(qx) | (spread_bits(qy) << 1);
150	    }
151	    qsort(index->entries, count, sizeof(*index->entries), compare_entries);
152	    index->count = count;
153	    index->node_count = node_count;
154	    build_context context = {index->nodes, 0};
155	    index->root = build_nodes(&context, index->entries, 0, count);
156	    *out_index = index;
157	    return SPATIAL_STATUS_OK;
158	}
