165	size_t spatial_index_count(const spatial_index *index) { return index == NULL ? 0 : index->count; }
166	
167	static void collect_hits(const spatial_index *index, uint32_t node_index, spatial_bounds query, hit_list *hits) {
168	    if (hits->oom || !intersects(index->nodes[node_index].bounds, query)) return;
169	    const packed_node *node = &index->nodes[node_index];
170	    if (node->leaf) {
171	        if (hits->count == hits->capacity) {
172	            size_t next = hits->capacity == 0 ? 32 : hits->capacity * 2;
173	            if (next < hits->capacity || next > SIZE_MAX / sizeof(*hits->items)) { hits->oom = true; return; }
174	            uint32_t *items = realloc(hits->items, next * sizeof(*items));
175	            if (items == NULL) { hits->oom = true; return; }
176	            hits->items = items; hits->capacity = next;
177	        }
178	        hits->items[hits->count++] = index->entries[node->entry].source_index;
179	        return;
180	    }
181	    collect_hits(index, node->left, query, hits);
182	    collect_hits(index, node->right, query, hits);
183	}
184	
185	static int compare_indices(const void *left, const void *right) {
186	    uint32_t a = *(const uint32_t *)left, b = *(const uint32_t *)right;
187	    return a < b ? -1 : a > b ? 1 : 0;
188	}
