190	spatial_status spatial_index_query(const spatial_index *index, spatial_bounds viewport,
191	                                   size_t *out_record_indices, size_t capacity, size_t *out_count) {
192	    if (out_count == NULL) return SPATIAL_STATUS_INVALID;
193	    *out_count = 0;
194	    if (index == NULL || !bounds_valid(viewport) || (capacity != 0 && out_record_indices == NULL)) return SPATIAL_STATUS_INVALID;
195	    if (index->count == 0) return SPATIAL_STATUS_OK;
196	    hit_list hits = {0};
197	    collect_hits(index, index->root, viewport, &hits);
198	    if (hits.oom) { free(hits.items); return SPATIAL_STATUS_OOM; }
199	    if (hits.count > 1) qsort(hits.items, hits.count, sizeof(*hits.items), compare_indices);
200	    *out_count = hits.count;
201	    if (capacity < hits.count) { free(hits.items); return SPATIAL_STATUS_LIMIT; }
202	    for (size_t i = 0; i < hits.count; ++i) out_record_indices[i] = hits.items[i];
203	    free(hits.items);
204	    return SPATIAL_STATUS_OK;
205	}
